// ============================================================
// TutorBot · Modulo CONFIRMAR (paso 4 del wizard)
// Transicion SOLICITADA -> ASIGNADA. Antes de escribir se REVALIDA el cupo:
// entre el momento en que se mostraron las opciones y el momento en que el
// estudiante responde pudo entrar otra reserva (ver docs/06 · concurrencia).
// ============================================================
const ctx = $input.first().json;
const cfg = $('Config').first().json;

const DUR = Number(cfg.DURACION_MIN || 60);
const OCUPAN = ['ASIGNADA', 'CONFIRMADA'];
const norm = s => String(s == null ? '' : s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
const aMin = h => { const m = /^(\d{1,2}):(\d{2})/.exec(String(h == null ? '' : h).trim()); return m ? Number(m[1]) * 60 + Number(m[2]) : null; };

function filas(nodo) {
  try { return $(nodo).all().map(i => i.json).filter(r => r && Object.keys(r).length > 0); }
  catch (e) { return []; }
}
const tutores  = filas('Leer TUTORES').filter(t => String(t.id_tutor || '') !== '');
const dispo    = filas('Leer DISPONIBILIDAD').filter(d => String(d.id_tutor || '') !== '');
const tutorias = filas('Leer TUTORIAS').filter(t => String(t.id_tutoria || '') !== '');

function sesion(pantalla, paso, datos) {
  return {
    telegram_user: ctx.telegram_user, pantalla_actual: pantalla, paso_actual: String(paso),
    datos_parciales: JSON.stringify(datos || {}), actualizado_en: cfg.ahora_iso
  };
}
function salida(o) {
  return [{ json: Object.assign({
    telegram_user: ctx.telegram_user, chat_id: ctx.chat_id, ruta: ctx.ruta, submodo: ctx.submodo,
    accion: 'sin_accion', estudiante_row: null, tutoria_row: null, notificar: null,
    evento: 'confirmacion', detalle: ''
  }, o) }];
}

const datos = ctx.datos || {};
const opciones = Array.isArray(datos.opciones) ? datos.opciones : [];
const filaPrevia = tutorias.find(t => String(t.id_tutoria) === String(datos.id_tutoria)) || {};

// --- El estudiante descarta ---
if (String(ctx.texto).trim() === '0') {
  return salida({
    mensaje: 'Descarte esas opciones. No quedo ninguna tutoria asignada.\n\nEscribe /menu para volver al menu.',
    sesion: sesion('MENU', 0, {}),
    accion: 'actualizar_tutoria',
    tutoria_row: Object.assign({}, filaPrevia, {
      id_tutoria: datos.id_tutoria, estado: 'CANCELADA',
      motivo: 'descartada por el estudiante en la confirmacion',
      fecha_actualizacion: cfg.ahora_iso
    }),
    evento: 'opciones_descartadas',
    detalle: String(datos.id_tutoria || '')
  });
}

const n = parseInt(String(ctx.texto).replace(/[^0-9]/g, ''), 10);
if (!n || n < 1 || n > opciones.length) {
  return salida({
    mensaje: 'Responde con un numero entre 1 y ' + opciones.length + ', o 0 para descartar.\n\n' +
             opciones.map((o, i) => (i + 1) + ') ' + o.hora + ' a ' + o.hora_fin + ' con ' + o.nombre_tutor).join('\n'),
    sesion: sesion('SOL_CONFIRMA', 3, datos),
    evento: 'confirmacion_invalida',
    detalle: String(ctx.texto).slice(0, 20)
  });
}

const op = opciones[n - 1];
const tutor = tutores.find(t => String(t.id_tutor) === String(op.id_tutor));
const ini = aMin(op.hora), fin = aMin(op.hora_fin);

// ---- REVALIDACION antes de escribir ----
function rechazar(motivo) {
  return salida({
    mensaje: 'Esa opcion ya no esta disponible: ' + motivo + '\n\nVuelve a intentarlo con la opcion 1 del menu.',
    sesion: sesion('MENU', 0, {}),
    accion: 'actualizar_tutoria',
    tutoria_row: Object.assign({}, filaPrevia, {
      id_tutoria: datos.id_tutoria, estado: 'SIN_DISPONIBILIDAD',
      motivo: 'revalidacion fallida: ' + motivo, fecha_actualizacion: cfg.ahora_iso
    }),
    evento: 'revalidacion_fallida',
    detalle: motivo
  });
}
if (!tutor || norm(tutor.estado) !== 'activo') return rechazar('el tutor ya no esta activo.');

const franjaOk = dispo.some(x =>
  String(x.id_tutor) === String(op.id_tutor) &&
  norm(x.dia_semana) === norm(datos.dia) &&
  ['libre', 'activa', 'activo', ''].includes(norm(x.estado)) &&
  aMin(x.hora_inicio) !== null && aMin(x.hora_fin) !== null &&
  aMin(x.hora_inicio) <= ini && aMin(x.hora_fin) >= fin
);
if (!franjaOk) return rechazar('el tutor cerro esa franja de disponibilidad.');

const choca = (r) => {
  const ri = aMin(r.hora);
  if (ri === null) return false;
  const rf = aMin(r.hora_fin) !== null ? aMin(r.hora_fin) : ri + Number(r.duracion_min || DUR);
  return ini < rf && ri < fin;
};
const vigentes = tutorias.filter(t =>
  String(t.fecha) === String(datos.fecha) &&
  String(t.id_tutoria) !== String(datos.id_tutoria) &&
  OCUPAN.includes(String(t.estado || '').toUpperCase())
);
if (vigentes.some(r => String(r.id_tutor) === String(op.id_tutor) && choca(r))) {
  return rechazar('otro estudiante reservo ese horario primero.');
}
if (vigentes.some(r => String(r.id_estudiante) === String(ctx.id_estudiante) && choca(r))) {
  return rechazar('ya tienes otra tutoria a esa misma hora.');
}

// ---- Asignacion ----
const fila = Object.assign({}, filaPrevia, {
  id_tutoria: datos.id_tutoria,
  id_estudiante: ctx.id_estudiante,
  nombre_estudiante: ctx.nombre_estudiante,
  telegram_user_estudiante: ctx.chat_id,
  id_tutor: String(op.id_tutor),
  nombre_tutor: String(op.nombre_tutor),
  materia: String(datos.materia),
  fecha: String(datos.fecha),
  dia_semana: String(datos.dia),
  hora: op.hora, hora_fin: op.hora_fin, duracion_min: DUR,
  estado: 'ASIGNADA',
  id_dispo: String(op.id_dispo || ''),
  fecha_solicitud: filaPrevia.fecha_solicitud || cfg.ahora_iso,
  fecha_actualizacion: cfg.ahora_iso,
  recordatorio_enviado: '', motivo: ''
});

const avisoTutor = [
  'Nueva tutoria ASIGNADA',
  '',
  'Materia: ' + fila.materia,
  'Estudiante: ' + fila.nombre_estudiante + ' (' + fila.id_estudiante + ')',
  'Fecha: ' + fila.fecha + ' (' + fila.dia_semana.toLowerCase() + ')',
  'Hora: ' + fila.hora + ' a ' + fila.hora_fin,
  'Codigo: ' + fila.id_tutoria,
  '',
  'Para aceptarla: /confirmar ' + fila.id_tutoria,
  'Al terminarla: /finalizar ' + fila.id_tutoria
].join('\n');

return salida({
  mensaje: [
    'Tutoria asignada.',
    '',
    'Materia: ' + fila.materia,
    'Tutor: ' + fila.nombre_tutor,
    'Fecha: ' + fila.fecha + ' (' + fila.dia_semana.toLowerCase() + ')',
    'Hora: ' + fila.hora + ' a ' + fila.hora_fin,
    'Codigo: ' + fila.id_tutoria,
    'Estado: ASIGNADA (ya avise al tutor para que la confirme)',
    '',
    'Te enviare un recordatorio ' + (cfg.HORAS_RECORDATORIO || 24) + ' horas antes.'
  ].join('\n'),
  sesion: sesion('MENU', 0, {}),
  accion: 'actualizar_tutoria',
  tutoria_row: fila,
  notificar: {
    chat_id: String(tutor.telegram_chat_id || ''),
    mensaje: avisoTutor
  },
  evento: 'tutoria_asignada',
  detalle: fila.id_tutoria + ' | ' + fila.id_tutor + ' | ' + fila.fecha + ' ' + fila.hora
});

// ============================================================
// TutorBot · Normalizar respuesta del modulo
// Punto unico de convergencia de los 7 modulos. Garantiza que, sin importar
// que rama se ejecuto, exista siempre: mensaje, sesion, accion y fila de log.
// Hay una copia de este nodo por rama: 'Normalizar REGISTRO', 'Normalizar MENU', etc.
// Los nodos siguientes de cada rama leen del suyo, no de uno compartido.
// ============================================================
const it = $input.first().json;
const cfg = $('Config').first().json;

// ---- Rastro de la IA (si esta ejecucion paso por el interprete) ----
// $('Nodo') lanza error si el nodo no se ejecuto en esta rama: se captura.
// En el sub-workflow el contexto llega por 'Ejecutar modulo'; en un flujo unico
// viene del nodo de validacion. Se prueban los dos y se ignora el que no exista.
let ia = null;
for (const nombre of ['Ejecutar modulo', 'Validar interpretacion IA']) {
  try {
    const j = $(nombre).first().json;
    if (j && j.ia_usada) { ia = j; break; }
  } catch (e) { /* ese nodo no existe en este workflow */ }
}

const ACCIONES = ['sin_accion', 'crear_estudiante', 'crear_tutoria', 'actualizar_tutoria'];
const accion = ACCIONES.includes(it.accion) ? it.accion : 'sin_accion';

// Telegram rechaza mensajes vacios y corta en 4096 caracteres
let mensaje = String(it.mensaje == null ? '' : it.mensaje).trim();
if (!mensaje) mensaje = 'Ocurrio algo inesperado y no pude preparar una respuesta. Escribe /menu para reiniciar.';
// El estudiante debe VER lo que el modelo entendio antes de que se reserve nada
if (ia && ia.ia_aviso) mensaje = ia.ia_aviso + '\n\n' + mensaje;
// Telegram interpreta el texto como HTML: hay que escapar estos tres caracteres.
// Sin esto, un "<" en el texto rompe el envio entero con "can't parse entities".
const esc = t => String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
mensaje = esc(mensaje);
if (mensaje.length > 3900) mensaje = mensaje.slice(0, 3900) + '\n\n[mensaje recortado]';

const sesion = it.sesion || {
  telegram_user: it.telegram_user, pantalla_actual: 'MENU', paso_actual: '0',
  datos_parciales: '{}', actualizado_en: cfg.ahora_iso
};

const tutoria = it.tutoria_row || null;
const estudiante = it.estudiante_row || null;

let entidad = 'sesion', id_entidad = String(it.telegram_user || '');
if (tutoria)        { entidad = 'tutoria';    id_entidad = String(tutoria.id_tutoria || ''); }
else if (estudiante){ entidad = 'estudiante'; id_entidad = String(estudiante.id_estudiante || ''); }

// Fila de LOG_EVENTOS: es la trazabilidad que pide la coordinacion
const log = {
  id_evento: 'EV-' + String(cfg.ahora_iso).replace(/[^0-9]/g, '').slice(0, 14) + '-' + Math.floor(Math.random() * 9000 + 1000),
  timestamp: cfg.ahora_iso,
  telegram_user: String(it.telegram_user || ''),
  evento: String(it.evento || 'interaccion'),
  entidad: entidad,
  id_entidad: id_entidad,
  detalle: String(it.detalle == null ? '' : it.detalle).slice(0, 300)
};
// Auditoria del uso de IA: que se le mando, que devolvio y si se acepto
if (ia) {
  log.detalle = (log.detalle + ' | IA:' + ia.ia_intencion +
    '/' + (ia.ia_materia || '-') + '/' + (ia.ia_fecha || '-') +
    ' conf=' + ia.ia_confianza +
    (ia.ia_fallo ? ' descartado=' + ia.ia_fallo : '') +
    ' txt="' + String(ia.ia_texto_original || '').slice(0, 60) + '"').slice(0, 300);
}

return [{
  json: {
    telegram_user: String(it.telegram_user || ''),
    chat_id: String(it.chat_id || ''),
    ruta: it.ruta || '', submodo: it.submodo || '',
    mensaje: mensaje,
    sesion: sesion,
    accion: accion,
    estudiante_row: estudiante,
    tutoria_row: tutoria,
    notificar: it.notificar && it.notificar.chat_id
      ? Object.assign({}, it.notificar, { mensaje: esc(it.notificar.mensaje) })
      : null,
    ia_usada: !!ia,
    ia_fallo: ia ? ia.ia_fallo : '',
    log: log
  }
}];

// ============================================================
// TutorBot · Verificar doble reserva (control post-escritura)
// Google Sheets no es transaccional: dos ejecuciones simultaneas pueden
// escribir el mismo horario. Estrategia: releer TUTORIAS DESPUES de escribir
// y, si hay dos reservas solapadas para el mismo tutor, gana la de
// fecha_solicitud mas antigua (empate: id_tutoria menor). La perdedora se
// libera automaticamente y se avisa al estudiante.
// ============================================================
const cons = $('Normalizar respuesta').first().json;
const cfg = $('Config').first().json;
const nueva = cons.tutoria_row;

// Telegram interpreta el texto como HTML: hay que escapar estos tres caracteres.
// Sin esto, un "<" en el texto rompe el envio entero con "can't parse entities".
const esc = t => String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const OCUPAN = ['ASIGNADA', 'CONFIRMADA'];
const DUR = Number(cfg.DURACION_MIN || 60);
const aMin = h => { const m = /^(\d{1,2}):(\d{2})/.exec(String(h == null ? '' : h).trim()); return m ? Number(m[1]) * 60 + Number(m[2]) : null; };

function base(resultado, extra) {
  const salida = Object.assign({
    resultado: resultado,
    chat_id: cons.chat_id,
    mensaje: cons.mensaje,
    id_tutoria: nueva ? String(nueva.id_tutoria || '') : '',
    tutoria_row: nueva
  }, extra || {});
  // cons.mensaje ya viene escapado; lo que se arme aqui tambien debe estarlo
  if (extra && extra.mensaje) salida.mensaje = esc(extra.mensaje);
  return [{ json: salida }];
}

// Solo una asignacion vigente puede generar conflicto de agenda
if (!nueva || String(nueva.estado || '').toUpperCase() !== 'ASIGNADA') {
  return base(cons.notificar ? 'notificar' : 'solo_responder');
}

const filas = $('Releer TUTORIAS').all().map(i => i.json)
  .filter(r => r && String(r.id_tutoria || '') !== '');

const ini = aMin(nueva.hora);
const fin = aMin(nueva.hora_fin) !== null ? aMin(nueva.hora_fin) : (ini === null ? null : ini + DUR);
if (ini === null || fin === null) return base(cons.notificar ? 'notificar' : 'solo_responder');

const choca = r => {
  const ri = aMin(r.hora);
  if (ri === null) return false;
  const rf = aMin(r.hora_fin) !== null ? aMin(r.hora_fin) : ri + Number(r.duracion_min || DUR);
  return ini < rf && ri < fin;
};

const conflictos = filas.filter(r =>
  String(r.id_tutoria) !== String(nueva.id_tutoria) &&
  String(r.id_tutor) === String(nueva.id_tutor) &&
  String(r.fecha) === String(nueva.fecha) &&
  OCUPAN.includes(String(r.estado || '').toUpperCase()) &&
  choca(r)
);

if (conflictos.length === 0) {
  return base(cons.notificar ? 'notificar' : 'solo_responder');
}

// Desempate determinista
const orden = (a, b) =>
  String(a.fecha_solicitud || '').localeCompare(String(b.fecha_solicitud || '')) ||
  String(a.id_tutoria).localeCompare(String(b.id_tutoria));
const ganador = [nueva].concat(conflictos).sort(orden)[0];

if (String(ganador.id_tutoria) === String(nueva.id_tutoria)) {
  // Nuestra reserva es la mas antigua: se mantiene y se deja constancia
  return base(cons.notificar ? 'notificar' : 'solo_responder', {
    aviso_interno: 'conflicto detectado y resuelto a favor de ' + nueva.id_tutoria
  });
}

// Perdimos: se libera la reserva recien escrita
const liberada = Object.assign({}, nueva, {
  estado: 'CANCELADA',
  motivo: 'conflicto de disponibilidad: el horario fue reservado antes por ' + ganador.id_tutoria,
  fecha_actualizacion: cfg.ahora_iso
});

return base('conflicto', {
  tutoria_row: liberada,
  mensaje: [
    'Tuve que liberar tu reserva.',
    '',
    'Mientras confirmabas, otro estudiante tomo el horario de ' + nueva.hora + ' con ' + nueva.nombre_tutor +
    ' el ' + nueva.fecha + '.',
    'Tu solicitud quedo CANCELADA y el cupo no se duplico.',
    '',
    'Escribe 1 para buscar otro horario disponible.'
  ].join('\n'),
  id_conflicto: String(ganador.id_tutoria)
});
